INSERT INTO arena_exercises (lesson_id,question,options,answer) VALUES (1,'Qual é a primeira etapa antes de escolher um investimento?',JSON_ARRAY('Definir objetivo, prazo e tolerância a risco','Seguir a indicação mais comentada','Escolher sempre o ativo que mais subiu','Investir sem montar orçamento'),0);
